package com.slss.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="production_batches") public class ProductionBatch { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="batch_name",unique=true,nullable=false) String batchName; @Column(nullable=false) String status="DRAFT"; Instant createdAt=Instant.now(); @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="tenant_id") CustomerTenant tenant; @OneToMany(mappedBy="batch",cascade=CascadeType.ALL,orphanRemoval=true) List<Asset> assets=new ArrayList<>(); public CustomerTenant getTenant(){return tenant;} public void setTenant(CustomerTenant v){tenant=v;} public Long getId(){return id;} public String getBatchName(){return batchName;} public void setBatchName(String v){batchName=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Instant getCreatedAt(){return createdAt;} public List<Asset> getAssets(){return assets;} }
